/// <summary>
/// This method returns CW physical invent.
/// </summary>
/// <param name="_inventOnHandQty">InventOnHandQty class</param>
/// <returns>CW physicl invent</returns>
public PdsCWInventQty pdsCWOnHandQty(InventOnHandQty _inventOnHandQty)
{
    return _inventOnHandQty.availPhysical();
}

public static InventDimOnHand newAvailAndPhysical(
    ItemId                  _itemId,
    InventDim               _inventDimCriteria,
    InventDimParm           _inventDimParmCriteria,
    InventDimOnHandLevel    _inventDimOnHandLevel,
    InventDimParm           _inventDimParmOnHandLevel)
{
    MobInventOnhand_availAndPhysical inventDimOnHand = new MobInventOnhand_availAndPhysical();

    inventDimOnHand.parmItemIdCriteria(_itemId);
    inventDimOnHand.parmInventDimCriteria(_inventDimCriteria);
    inventDimOnHand.parmInventDimParmCriteria(_inventDimParmCriteria);
    inventDimOnHand.parmInventDimOnHandLevel(_inventDimOnHandLevel);
    inventDimOnHand.parmInventDimParmOnHandLevel(_inventDimParmOnHandLevel);
    inventDimOnHand.parmOnlyPositiveOnHands(NoYes::No);
    inventDimOnHand.initialize();
    return inventDimOnHand;
}

public static void populateLookupResponse(TFMLookupResponseElement _lookupResponse, ItemId _itemId, InventLocationId _locationId, WMSLocationId _wmsLocationId, str _fieldNameToOmit)
{
    MobInventOnhand_availAndPhysical    onHand;
    InventDimOnHandIterator             iter;
    InventDimOnHandMember               member;
    InventSum                           inventSum;        
    InventDim                           inventDimCrit;
    InventDimParm                       inventDimParmCrit, inventDimParmOnHandLevel;
    MobBackendId                        backendId;
    InventDim                           inventDim;
    InventDimOnHandLevel                level;
    InventLocationId                    inventLocationId;
    InventTable                         iTable;

    inventLocationId = _locationId;

    // The warehouse element can contain the "All" value
    // In this case all warehouses should be searched. In this case we "blank" the inventLocationId
    if (inventLocationId == MobConstants::All())
    {
        inventLocationId = '';
    }

    // Known dimensions

    inventDimCrit.InventLocationId = inventLocationId;
    inventDimCrit.wMSLocationId = _wmsLocationId;
    inventDimCrit = InventDim::findOrCreate(inventDimCrit);

    // Determine which of the known dimensions to use
    inventDimParmCrit.InventLocationIdFlag = inventLocationId ? true : false;
    inventDimParmCrit.wMSLocationIdFlag = _wmsLocationId ? true :false;

    level = InventDimOnHandLevel::DimParm;

    // Only matters for level DimParm.  Determines the level of detail returned
    inventDimParmOnHandLevel.setAllInventDim();
    inventDimParmOnHandLevel.ItemIdFlag = true;
    inventDimParmOnHandLevel.InventLocationIdFlag = inventLocationId ? true : false;
    inventDimParmOnHandLevel.WMSLocationIdFlag = true;
    MobInventOnhand_availAndPhysical::addOmissionFields(_fieldNameToOmit, inventDimParmOnHandLevel);
    while select ItemId from iTable where iTable.ItemId like _itemId || !_itemId
    {
        onHand = MobInventOnhand_availAndPhysical::newAvailAndPhysical(_itemId ? iTable.ItemId : _itemId, inventDimCrit, InventDimParmCrit, level, inventDimParmOnHandLevel);

        iter = onHand.onHandIterator();
        while (iter.more())
        {
            member = iter.value();
            inventSum = MobInventOnhand_availAndPhysical::findRealRecord(member.parmInventDimId(), member.parmItemId(), member.parmInventQty(),  member.pdsCWParmInventQty());
            if (!inventSum)
            {
                inventSum.RecId++;
                inventSum.InventDimId = member.parmInventDimId();
                inventSum.ItemId = member.parmItemId();
                inventSum.PhysicalInvent = member.parmInventQty();
                inventSum.AvailPhysical = member.pdsCWParmInventQty();
            }
            backendId = tableStr(inventSum) + '/' + fieldStr(inventSum,RecId) + '/' + int642Str(inventSum.recID) + '/' + _lookupResponse.contentType();
            _lookupResponse.addResponse(inventSum, backendId,null);

            iter.next();
        }
        if (!_itemId)
        {
            //only run once
            break;
        }
    }
}

protected static InventSum findRealRecord(InventDimId _inventDimid, ItemId _itemId, InventQty _physInvent, InventQty _availPhys) 
{
    InventSum iSum;
    select firstonly InventDimId, ItemId, PhysicalInvent, AvailPhysical, RecId from iSum where iSum.inventDimId == _inventDimid && iSum.ItemId == _itemId && iSum.AvailPhysical == _availPhys && iSum.PhysicalInvent == _physInvent;

    return iSum;
}

public static void addOmissionFields(FieldName _fieldNameToOmit, InventDimParm _inventDimParm)
{
    ListEnumerator  lEnum = strSplit(_fieldNameToOmit,';').getEnumerator();
    str             ignoreField;
    while (lEnum.moveNext())
    {
        ignoreField = lEnum.current();
        if (fieldName2Id(tableNum(InventDim),ignoreField) != 0)
        {
            _inventDimParm.( fieldName2Id( tableNum(InventDimParm),MobInventDimHelper::flagFieldName(ignoreField) ) ) = NoYes::No;
        }
    }
}
